    expect(getBody.settings.resend_api_key_configured).toBe(true);
    expect(typeof getBody.settings.resend_api_key_masked).toBe('string');
    expect(getBody.settings.resend_api_key_masked.length).toBeGreaterThan(0);
    expect(getBody.settings.resend_from_email).toBe('noreply@example.com');
    expect(getBody.settings.site_name).toBe('新版图文社区');
    expect(typeof getBody.stats.posts).toBe('number');
    expect(typeof getBody.stats.users).toBe('number');
    expect(typeof getBody.stats.media).toBe('number');
    expect(typeof getBody.stats.clicks).toBe('number');

    // Updating other fields with empty resend_api_key preserves existing key
